<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';
$pdo=db();$stamp=bin2hex(random_bytes(5));$ids=[];$simulationId=0;
try{
    $plot=trim((string)($argv[1]??''));if($plot===''){$q=$pdo->query('SELECT p.code FROM plots p JOIN plot_roles pr ON pr.plot_id=p.plot_id AND pr.active=1 AND pr.simulation_active=1 WHERE p.status="active" GROUP BY p.plot_id HAVING COUNT(*)>=2 ORDER BY p.plot_id LIMIT 1');$plot=(string)$q->fetchColumn();}if($plot==='')throw new RuntimeException('No active story with at least two playable roles is available.');
    foreach(['Host','Guest']as$i=>$name){$email="toinky-smoke-{$stamp}-{$i}@example.invalid";$pdo->prepare('INSERT INTO users(email,password_hash,display_name) VALUES(?,?,?)')->execute([$email,password_hash(bin2hex(random_bytes(12)),PASSWORD_DEFAULT),"Smoke {$name}"]);$ids[]=(int)$pdo->lastInsertId();}
    // Task 5 Phase 1: hosted games run the PUBLISHED version, so createGame fails
// closed when a story has no published pointer. Fresh builds seed the stories
// as PUBLISHED with no version row, so publish the smoke story here when it
// has none, with the same snapshot submit() builds (mirrors the commerce
// guard test fixture, which publishes EMPTY_THRONE; the smoke story is the
// first active story with two playable roles, usually CONCEALED_FAILURE).
// No-op on a live install where the pointer already exists.
$plotQ=$pdo->prepare('SELECT plot_id,published_plot_version_id FROM plots WHERE code=? AND status="active"');$plotQ->execute([$plot]);$plotRow=$plotQ->fetch();
if($plotRow&&empty($plotRow['published_plot_version_id'])){require_once $root.'/app/StoryAuthoringService.php';$smokeAdmin=$pdo->query('SELECT user_id FROM users WHERE is_admin=1 ORDER BY user_id LIMIT 1')->fetch();if(!$smokeAdmin){$pdo->prepare('INSERT INTO users(email,password_hash,display_name,is_admin,email_verified_at_utc) VALUES(?,?,?,1,UTC_TIMESTAMP())')->execute(['smoke-test-admin@toinky.invalid','!','Smoke Test Admin']);$smokeAdmin=['user_id'=>(int)$pdo->lastInsertId()];}$plotId=(int)$plotRow['plot_id'];$snapshot=json_encode(['plot'=>StoryAuthoringService::story($plotId),'content'=>StoryAuthoringService::workspace($plotId)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$vq=$pdo->prepare('SELECT COALESCE(MAX(version_no),0)+1 FROM plot_versions WHERE plot_id=?');$vq->execute([$plotId]);$versionNo=(int)$vq->fetchColumn();$adminId=(int)$smokeAdmin['user_id'];$pdo->prepare('INSERT INTO plot_versions(plot_id,version_no,workflow_status,snapshot_json,submitted_by_user_id,reviewed_by_user_id,reviewed_at_utc) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP())')->execute([$plotId,$versionNo,'PUBLISHED',$snapshot,$adminId,$adminId]);$pdo->prepare('UPDATE plots SET published_plot_version_id=?,workflow_status="PUBLISHED" WHERE plot_id=?')->execute([(int)$pdo->lastInsertId(),$plotId]);}
$lobby=LobbyService::createGame($ids[0],$plot,3600);$gid=(int)$lobby['game']['game_id'];$simulationId=(int)$lobby['game']['simulation_id'];LobbyService::joinByCode($ids[1],(string)$lobby['game']['join_code']);
    $q=$pdo->prepare('SELECT character_id FROM characters WHERE simulation_id=? ORDER BY character_id LIMIT 2');$q->execute([$simulationId]);$chars=array_map('intval',array_column($q->fetchAll(),'character_id'));if(count($chars)<2)throw new RuntimeException('Smoke story did not instantiate two characters.');
    LobbyService::claimCharacter($gid,$ids[0],$chars[0]);$blocked=false;try{LobbyService::claimCharacter($gid,$ids[1],$chars[0]);}catch(RuntimeException$e){$blocked=true;}if(!$blocked)throw new RuntimeException('Duplicate character claim was not rejected.');
    LobbyService::claimCharacter($gid,$ids[1],$chars[1]);LobbyService::startGame($gid,$ids[0]);
    $q=$pdo->prepare('SELECT status FROM games WHERE game_id=?');$q->execute([$gid]);if($q->fetchColumn()!=='RUNNING')throw new RuntimeException('Host start did not put the game in RUNNING status.');
    $q=$pdo->prepare('SELECT character_id,controller_type FROM characters WHERE simulation_id=?');$q->execute([$simulationId]);$controllers=[];foreach($q->fetchAll()as$r)$controllers[(int)$r['character_id']]=$r['controller_type'];if(($controllers[$chars[0]]??null)!=='HUMAN'||($controllers[$chars[1]]??null)!=='HUMAN')throw new RuntimeException('Claimed characters were not assigned HUMAN control.');foreach($controllers as$cid=>$type)if(!in_array($cid,$chars,true)&&$type!=='AI')throw new RuntimeException('An unclaimed character was not assigned AI control.');
    echo "PASS: {$plot} lobby creation, code join, atomic claims, host start, and AI fallback.\n";
}catch(Throwable$e){fwrite(STDERR,'FAIL: '.$e->getMessage()."\n");exit(1);}finally{if($simulationId>0){$q=$pdo->prepare('DELETE FROM simulations WHERE simulation_id=?');$q->execute([$simulationId]);}foreach($ids as$id){$q=$pdo->prepare('DELETE FROM users WHERE user_id=?');$q->execute([$id]);}}
